using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side shipment service with in-memory seed data.
/// Replace with EF Core/database access for production.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments = GenerateSeedData();
    private static int _nextId = 11;
    private static readonly object _lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(
                s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        lock (_lock)
        {
            var results = _shipments
                .Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase))
                .ToList();
            return Task.FromResult(results);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
                shipment.Status = status;
        }
        return Task.CompletedTask;
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        lock (_lock)
        {
            shipment.Id = _nextId++;
            shipment.TrackingNumber = $"SHP-{shipment.Id:D6}";
            shipment.ShippedDate = DateTime.UtcNow;
            shipment.EstimatedDelivery = DateTime.UtcNow.AddDays(Random.Shared.Next(3, 14));
            shipment.Status = ShipmentStatus.Pending;
            _shipments.Add(shipment);
            return Task.FromResult(shipment);
        }
    }

    private static List<Shipment> GenerateSeedData() =>
    [
        new() { Id = 1, TrackingNumber = "SHP-000001", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "customer@example.com", Description = "Electronics - Laptop" },
