        new() { Id = 6, TrackingNumber = "SHP-000006", Origin = "Dubai, UAE", Destination = "Toronto, Canada", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-6), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "client@example.com", Description = "Construction Materials" },
